        bivector = x[..., :2].flip(dims=(-1,))
        rest     = x[..., 2:]
        if rest.shape[-1] == 0:
            return bivector
        return torch.cat([bivector, rest], dim=-1)

    def reverse(self, y):
        """Both representations are their own inverse."""
        return self.forward(y)

